import{_ as a,o as n,c as s,a0 as t}from"./chunks/framework.bcCluOOn.js";const h=JSON.parse('{"title":"Entities & Data Models","description":"","frontmatter":{},"headers":[],"relativePath":"specification/entities.md","filePath":"specification/entities.md"}'),i={name:"specification/entities.md"};function o(d,e,p,l,r,c){return n(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="entities-data-models" tabindex="-1">Entities &amp; Data Models <a class="header-anchor" href="#entities-data-models" aria-label="Permalink to &quot;Entities &amp; Data Models&quot;">​</a></h1><p>In AAYU, the <code>entity</code> block is the fundamental building block for data modeling. An <code>entity</code> represents a discrete business object, mapping directly to a database table or a document collection in the generated backend.</p><h2 id="defining-an-entity" tabindex="-1">Defining an Entity <a class="header-anchor" href="#defining-an-entity" aria-label="Permalink to &quot;Defining an Entity&quot;">​</a></h2><p>An entity is declared using the <code>entity</code> keyword, followed by its name (PascalCase is recommended) and a period. Inside the entity block, properties are declared using their type and name.</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>entity User.</span></span>
<span class="line"><span>    text username.</span></span>
<span class="line"><span>    text email.</span></span>
<span class="line"><span>    boolean is_active.</span></span>
<span class="line"><span>end.</span></span></code></pre></div><h2 id="automatic-properties" tabindex="-1">Automatic Properties <a class="header-anchor" href="#automatic-properties" aria-label="Permalink to &quot;Automatic Properties&quot;">​</a></h2><p>By default, the AAYU compiler automatically provisions standard tracking fields for every entity:</p><ul><li><code>id</code>: A unique primary key (auto-incrementing integer or UUID depending on the target engine).</li><li><code>created_at</code>: The timestamp when the record was created.</li></ul><p><em>Note: In future versions of the specification, the <code>id</code> type behavior will be configurable globally or per-entity.</em></p><h2 id="using-entities-in-code" tabindex="-1">Using Entities in Code <a class="header-anchor" href="#using-entities-in-code" aria-label="Permalink to &quot;Using Entities in Code&quot;">​</a></h2><p>Once an entity is defined, the AAYU Standard Library (<code>db</code> module) provides built-in functions to interact with it.</p><h3 id="creating-records" tabindex="-1">Creating Records <a class="header-anchor" href="#creating-records" aria-label="Permalink to &quot;Creating Records&quot;">​</a></h3><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>map new_user.</span></span>
<span class="line"><span>set &quot;username&quot; to &quot;alice&quot; in new_user.</span></span>
<span class="line"><span>set &quot;email&quot; to &quot;alice@example.com&quot; in new_user.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>create User with new_user.</span></span></code></pre></div><h3 id="finding-records" tabindex="-1">Finding Records <a class="header-anchor" href="#finding-records" aria-label="Permalink to &quot;Finding Records&quot;">​</a></h3><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Retrieve all users</span></span>
<span class="line"><span>list all_users is find User.</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Retrieve a specific user</span></span>
<span class="line"><span>list admins is find User where &quot;is_active&quot; equal to true.</span></span></code></pre></div><h3 id="updating-records" tabindex="-1">Updating Records <a class="header-anchor" href="#updating-records" aria-label="Permalink to &quot;Updating Records&quot;">​</a></h3><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>map update_data.</span></span>
<span class="line"><span>set &quot;is_active&quot; to false in update_data.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>update User where &quot;username&quot; equal to &quot;alice&quot; with update_data.</span></span></code></pre></div><h3 id="deleting-records" tabindex="-1">Deleting Records <a class="header-anchor" href="#deleting-records" aria-label="Permalink to &quot;Deleting Records&quot;">​</a></h3><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>delete User where &quot;username&quot; equal to &quot;alice&quot;.</span></span></code></pre></div>`,19)])])}const g=a(i,[["render",o]]);export{h as __pageData,g as default};
